def check_expression(expression):
    # Split the expression into tokens
    tokens = expression.split()

    # Initialize an empty stack for tracking opening brackets
    stack = []

    # Iterate through each token in the expression
    for token in tokens:
        # If the token is an opening bracket, push it onto the stack
        if token == '(' or token == '[' or token == '{':
            stack.append(token)
        # If the token is a closing bracket
        elif token == ')' or token == ']' or token == '}':
            # Pop from the stack while the top of the stack is an opening bracket
            while stack and stack[-1] != '(' and stack[-1] != '[' and stack[-1] != '{':
                stack.pop()
            # If the stack is empty after popping all opening brackets, the expression is balanced
            if not stack:
                return True
            else:
                # Otherwise, the expression is unbalanced
                return False

    # If the loop completes without returning False, the expression is balanced
    return True

def check_expression(expression):
    """
    Check if the given expression is balanced or not.

    Args:
    expression (str): The mathematical expression to check.

    Returns:
    bool: True if the expression is balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) > 0 and stack[-1] == '(':
                stack.pop()
            else:
                return False

    return len(stack) == 0

